import { readFileSync, existsSync, readdirSync, mkdirSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { isDeepStrictEqual as equal } from 'node:util';
const root='.agentdoc/v07-setup-20260911T122653Z/evidence/exploration/round-05';
const output='.agentdoc/v07-setup-20260911T122653Z/evidence/round05-analysis';
const read=p=>JSON.parse(readFileSync(p,'utf8'));
const hash=data=>createHash('sha256').update(data).digest('hex');
const objectHash=data=>hash(JSON.stringify(data));
const protocol=read(root+'/protocol.preregistered.json');
const expected=[...protocol.controls.map(e=>({...e,kind:'control'})),...protocol.candidates.map(e=>({...e,kind:'candidate'}))];
const canonical={profile:'active',policy:'free',inputSchedule:'uniform',management:'none',menuVisitSeconds:0};
const errors=[];
const check=(ok,label)=>{if(!ok)errors.push(label);};
check(protocol.round===5&&protocol.schemaVersion===2&&protocol.progressionParameterVersion===2,'round05 registered protocol version');
check(protocol.experimentStage==='exploration'&&protocol.phase==='candidate'&&protocol.selectedExperiment===null,'unselected exploration protocol');
check(protocol.controls.length===5&&protocol.candidates.length===3&&expected.length===8,'five controls and three candidates');
check(hash(readFileSync(root+'/protocol.preregistered.json'))==='08d704cd53c453fc79776dc19e340265cb1de8922f666544b7410ad9230ed722','round05 prepared official protocol exact bytes');
const archiveCache=new Map();
const archiveManifest=path=>{
 if(archiveCache.has(path))return archiveCache.get(path);
 const result=spawnSync('python3',['-c',
 'import tarfile,hashlib,json,sys\nwith tarfile.open(sys.argv[1]) as t:\n print(json.dumps({m.name:hashlib.sha256(t.extractfile(m).read()).hexdigest() for m in t if m.isfile()}))',path],{encoding:'utf8'});
 if(result.status!==0)throw Error(result.stderr);
 const data=JSON.parse(result.stdout);archiveCache.set(path,data);return data;
};
const popQ=(values,q)=>{
 const sorted=[...values].sort((a,b)=>(a??Infinity)-(b??Infinity));
 return sorted.length?sorted[Math.floor((sorted.length-1)*q)]:null;
};
const stats=values=>{
 const reached=values.filter(v=>v!==null);
 check(values.every(v=>v===null||typeof v==='number'&&Number.isFinite(v)),'finite metric');
 const quantiles=sample=>({p10:popQ(sample,.1),p50:popQ(sample,.5),p90:popQ(sample,.9),worst:popQ(sample,1)});
 return {samples:values.length,reached:reached.length,unreached:values.length-reached.length,
  population:quantiles(values),conditional:quantiles(reached),minimum:reached.length?Math.min(...reached):null};
};
const event=(run,kind,id='')=>{
 const records=run.records.filter(r=>r.kind===kind&&r.id===id);
 check(records.length<=1,'duplicate event '+run.seed+'/'+kind+'/'+id);
 return records[0]?.sec??null;
};
const firstNames=['firstKillSec','firstRewardSec','firstLevelSec','firstCaptureSec','firstReadySec','firstOpenSec','firstAcceptedSec'];
const numberFields=['level','kills','coins','income','spent','companions','maxCompanionLevel','reincarnations','training','offers','rerolls','managementActions','feverStarts','inputCount','longestKillGapSec','longestMeaningfulGapSec','longestDiscoveryGapSec','eligibleHeroCount','eligibleMonsterCount','seenHeroCount','seenMonsterCount','chosenHeroCount','killedMonsterCount','capturedMonsterCount'];
const exactStats=values=>{
 const sorted=[...values].sort((a,b)=>BigInt(a)<BigInt(b)?-1:BigInt(a)>BigInt(b)?1:0);
 const at=q=>sorted[Math.floor((sorted.length-1)*q)]??null;
 return {samples:values.length,p10:at(.1),p50:at(.5),p90:at(.9),worst:at(1)};
};
const prefixPath=root+'/prefix-reference.json',prefixReference=read(prefixPath),prefixHash=hash(readFileSync(prefixPath));
check(prefixHash==='790e3441e749bc143b5930a4a11e5fbd6757bf22c5e2c2aabaf173f96b8fd278','frozen prefix reference hash');
const previousReference=read(prefixReference.sourceReport);
check(hash(readFileSync(prefixReference.sourceReport))===prefixReference.sourceReportSha256,'prefix source report hash');
check(objectHash(previousReference.runs)===prefixReference.sourceRawSha256,'prefix source raw hash');
const prefixFor=run=>{const last=run.checkpoints.at(-1),sec=last.firstAcceptedSec;return{
 seed:run.seed,firstEvents:Object.fromEntries(firstNames.map(n=>[n,last[n]])),
 recordsThroughFirstChoice:run.records.filter(r=>sec!==null&&r.sec<=sec),
 actionsThroughFirstChoice:run.actions.filter(a=>sec!==null&&a.sec<=sec)
};};
check(equal(prefixReference.prefixes,previousReference.runs.map(prefixFor)),'prefix reference exact extraction');
const recordedGap=(run,kinds)=>{
 const eventTicks=[...new Set(run.records.filter(r=>kinds.includes(r.kind)&&r.sec>7200&&r.sec<=43200).map(r=>Math.round(r.sec*10)))].sort((a,b)=>a-b);
 const ticks=[72000,...eventTicks,432000];
 return {startSec:7200,endSec:43200,distinctEventTicks:eventTicks.length,lastEventSec:eventTicks.length?eventTicks.at(-1)/10:null,
  longestGapSec:Math.max(...ticks.slice(1).map((n,i)=>n-ticks[i]))/10};
};
const reports=[];
const variants=[];
for(const exp of expected){
 const dir=root+'/'+exp.id, executionPath=existsSync(dir+'/execution-resume01.json')?dir+'/execution-resume01.json':dir+'/execution.json';
 if(!existsSync(executionPath)){variants.push({kind:exp.kind,id:exp.id,status:'NOT_STARTED'});continue;}
 const execution=read(executionPath);
 if(!execution.endedAt){variants.push({kind:exp.kind,id:exp.id,status:'INCOMPLETE',executionPath});continue;}
 const attempts=readdirSync(dir).filter(n=>/^execution.*\.json$/.test(n)).sort().map(name=>{
  const p=dir+'/'+name,e=read(p);
  for(const c of e.commands??[])if(c.sha256)check(hash(readFileSync(c.log))===c.sha256,exp.id+' historical log '+c.label);
  return {path:p,fileSha256:hash(readFileSync(p)),startedAt:e.startedAt,endedAt:e.endedAt??null,
   commands:(e.commands??[]).map(c=>({label:c.label,exitCode:c.exitCode,log:c.log})),
   sourceArchive:e.sourceArchive??null,buildArchive:e.buildArchive??null,repair:e.repair??null};
 });
 const complete=Boolean(execution.endedAt);
 const variant={kind:exp.kind,id:exp.id,parameters:exp.parameters,status:complete?'COMPLETED':'INCOMPLETE',executionPath,
  executionFileSha256:hash(readFileSync(executionPath)),attempts,commands:execution.commands.map(c=>({label:c.label,exitCode:c.exitCode,log:c.log})),
  full12h:execution['full-12h']??{status:'NOT_RECORDED'}};
 variants.push(variant);
 if(!complete)continue;
 const productionTest=execution.commands.find(command=>command.label==='production-tests');
 check(productionTest?.exitCode===0,exp.id+' production tests exit0');
 if(productionTest){
  const log=readFileSync(productionTest.log,'utf8').replace(/\u001b\[[0-9;]*m/g,'');
  check(equal(productionTest.argv,['npx','vitest','run','tests/progressionV7.test.ts','tests/formulas.test.ts','tests/engine.test.ts','tests/balance.test.ts']),exp.id+' production test command');
  check(/Test Files\s+4 passed \(4\)/.test(log)&&/Tests\s+94 passed \(94\)/.test(log),exp.id+' all94 production tests pass');
  variant.productionTests={exitCode:productionTest.exitCode,expectedFiles:4,expectedTests:94,summary:log.split('\n').filter(line=>/^\s*(?:Test Files|Tests)\s+/.test(line)).map(line=>line.trim()),log:productionTest.log,sha256:hash(readFileSync(productionTest.log))};
 }
 check(equal({...execution.experiment,kind:execution.experimentKind},exp),exp.id+' execution registration');
 check(Date.parse(execution.startedAt)>=Date.parse(protocol.frozenAt),exp.id+' preregistration precedes execution');
 check(execution.protocol.path===root+'/protocol.preregistered.json'&&execution.protocol.sha256===hash(readFileSync(execution.protocol.path)),exp.id+' execution protocol file hash');
 for(const c of execution.commands){if(c.sha256)check(hash(readFileSync(c.log))===c.sha256,exp.id+' log '+c.label);}
 for(const key of ['sourceArchive','evaluationArchive','buildArchive']){
  const a=execution[key];if(a)check(hash(readFileSync(a.path))===a.sha256,exp.id+' '+key+' bytes');
 }
 const files=['screening.json','full-12h.json'].filter(file=>existsSync(dir+'/'+file));
 for(const file of files){
  const path=dir+'/'+file,r=read(path),stage=r.screening?'screening':'full12h';
  const label=exp.id+'/'+stage;
  const reportBytes=readFileSync(path);
  const ledger=execution[r.screening?'screening':'full-12h'];
  check(ledger?.sha256===hash(reportBytes),label+' execution report file hash');
  for(const key of ['sourceDigest','evaluationDigest','rawSha256'])check(ledger?.[key]===r[key],label+' execution report '+key);
  check(ledger?.buildSha256===r.build.sha256&&equal(ledger?.experiment,r.experiment),label+' execution build/experiment binding');
  check(r.rawComplete===true&&r.phase==='candidate'&&r.seedSet==='exploration',label+' phase');
  check(equal(r.protocol,protocol),label+' frozen embedded protocol');
  check(r.protocolSha256===objectHash(r.protocol),label+' protocol hash');
  check(r.rawSha256===objectHash(r.runs),label+' raw hash');
  check(r.fixture===null&&r.fixtureSha256===objectHash(null),label+' fresh fixture');
  check(equal(r.policies,[canonical]),label+' canonical policy');
  check(equal(r.seeds,{start:10001,count:20}),label+' exploration seed registry');
  check(equal([...r.runs].map(run=>run.seed).sort((a,b)=>a-b),Array.from({length:20},(_,i)=>10001+i)),label+' all 20 seeds');
  check(r.experiment.id===exp.id&&r.experiment.kind===exp.kind&&r.experiment.parametersSha256===objectHash(exp.parameters),label+' experiment binding');
  check(r.experiment.contentRulesSha256===objectHash(Object.fromEntries(protocol.milestones.map(m=>[m.id,m.requirements]))),label+' content rules binding');
  check(equal(r.checkpointsMinutes,r.settings.checkpointsMinutes.filter(m=>!r.screening||m<=120)),label+' horizon');
  check(r.timing.modeledMinutes===(r.screening?120:720),label+' modeled horizon');
  const manifestPath=path+'.runs/manifest.json', manifest=read(manifestPath);
  check(manifest.binding===objectHash(manifest.identity),label+' manifest binding');
  for(const key of ['sourceDigest','evaluationDigest','protocolSha256','fixtureSha256','seedSet','seeds','policies','settings','screening','checkpointsMinutes','experiment'])
   check(equal(manifest.identity[key],r[key]),label+' identity '+key);
  check(manifest.identity.buildSha256===r.build.sha256&&r.build.sha256===objectHash(r.build.files),label+' build manifest');
  const sourceRaw=archiveManifest(execution.sourceArchive.path);
  const sourceEntries=Object.entries(sourceRaw);
  check(sourceEntries.every(([p])=>!p.startsWith('/')&&!p.startsWith('Users/')),label+' root-relative source archive');
  check(new Set(sourceEntries.map(([p])=>p)).size===sourceEntries.length,label+' unambiguous source path mapping');
  const source=Object.fromEntries(sourceEntries);
  const sourceFiles=Object.fromEntries(Object.entries(source).filter(([p])=>p.startsWith('src/')||p.startsWith('static/')||/^(package(-lock)?|tsconfig[^/]*)\.json$/.test(p)));
  check(hash(Object.keys(sourceFiles).sort().map(p=>p+'\0'+sourceFiles[p]).join('\n'))===r.sourceDigest,label+' archived source digest');
  const evaluationRaw=archiveManifest(execution.evaluationArchive.path);
  const evaluation=Object.fromEntries(Object.entries(evaluationRaw).filter(([p])=>p.startsWith('.harness/v7/')||p==='docs/v0.7/EVALUATION_PROTOCOL.json'));
  check(hash(Object.entries(evaluation).sort(([a],[b])=>a.localeCompare(b)).map(([p,h])=>p+'\0'+h).join('\n'))===r.evaluationDigest,label+' archived evaluator digest');
  if(execution.buildArchive){
   const build=archiveManifest(execution.buildArchive.path);
   for(const [p,h] of Object.entries(r.build.files))check(build[p]===h,label+' archived build '+p);
  }
  const rows=[];
  for(const run of r.runs){
   check(equal(run.policy,canonical),label+' raw canonical '+run.seed);
   check(Object.values(run.initial).every(v=>v===0),label+' zero initial '+run.seed);
   check(equal(run.checkpoints.map(c=>c.minutes),r.checkpointsMinutes),label+' raw checkpoints '+run.seed);
   const policyKey=Object.values(canonical).join('/');
   const seedFile=path+'.runs/'+hash(policyKey)+'/'+run.seed+'.json',raw=read(seedFile);
   check(raw.binding===manifest.binding&&raw.sha256===objectHash(raw.run)&&equal(raw.run,run),label+' raw seed binding '+run.seed);
   for(const cp of run.checkpoints){
    check(run.initial.coins+cp.income-cp.spent===cp.coins,label+' gold conservation '+run.seed+'/'+cp.minutes);
    for(const n of ['coins','income','spent','level','kills','companions','maxCompanionLevel'])check(Number.isSafeInteger(cp[n])&&cp[n]>=0,label+' safe integer '+n);
    for(const n of ['heroDamage','companionDamage','partyPower'])check(typeof cp[n]==='string'&&/^(0|[1-9][0-9]*)$/.test(cp[n]),label+' exact bigint '+n);
   }
   const last=run.checkpoints.at(-1);
   const row={seed:run.seed,...Object.fromEntries(firstNames.map(n=>[n,event(run,n)])),
    h70EligibleSec:event(run,'eligibleHero','h70'),h70SeenSec:event(run,'seenHero','h70'),h70ChosenSec:event(run,'chosenHero','h70')};
   for(const n of firstNames)check(last[n]===row[n],label+' checkpoint event '+run.seed+'/'+n);
   check(last.lastUnlockSec===row.h70EligibleSec,label+' final eligibility '+run.seed);
   if(row.firstOpenSec!==null)check(row.firstReadySec!==null&&row.firstReadySec<=row.firstOpenSec,label+' ready/open order');
   if(row.firstAcceptedSec!==null)check(row.firstOpenSec!==null&&row.firstOpenSec<=row.firstAcceptedSec,label+' open/accepted order');
   row.readyToOpenSec=row.firstOpenSec===null||row.firstReadySec===null?null:row.firstOpenSec-row.firstReadySec;
   row.openToAcceptedSec=row.firstAcceptedSec===null||row.firstOpenSec===null?null:row.firstAcceptedSec-row.firstOpenSec;
   row.terminal=Object.fromEntries(numberFields.map(n=>[n,last[n]]));
   row.terminalExactBigInt={heroDamage:last.heroDamage,companionDamage:last.companionDamage,partyPower:last.partyPower};
   row.distinctChosenHeroIds=[...new Set(run.actions.filter(a=>a.type==='heroChoose').map(a=>a.formId))];
   check(row.distinctChosenHeroIds.length===last.chosenHeroCount,label+' distinct actual chosen '+run.seed);
   row.lastHeroChoiceSec=run.actions.filter(a=>a.type==='heroChoose').at(-1)?.sec??null;
   if(!r.screening){
    const before=run.checkpoints.find(c=>c.minutes===480);
    row.post8h={kills8h:before.kills,kills12h:last.kills,killsAdded:last.kills-before.kills,
     reincarnations8h:before.reincarnations,reincarnations12h:last.reincarnations,reincarnationsAdded:last.reincarnations-before.reincarnations,
     distinctChosen8h:before.chosenHeroCount,distinctChosen12h:last.chosenHeroCount,distinctChosenAdded:last.chosenHeroCount-before.chosenHeroCount,
     partyPower8h:before.partyPower,partyPower12h:last.partyPower,partyPowerUnchanged:before.partyPower===last.partyPower,
     heroChoicesAfter8h:run.actions.filter(a=>a.type==='heroChoose'&&a.sec>28800).length};
    row.seenGap2to12h=recordedGap(run,['seenHero','seenMonster']);
    row.acquiredGap2to12h=recordedGap(run,['chosenHero','killedMonster']);
   }
   rows.push(row);
  }
  const metrics=Object.fromEntries([...firstNames,'h70EligibleSec','h70SeenSec','h70ChosenSec','readyToOpenSec','openToAcceptedSec'].map(n=>[n,stats(rows.map(row=>row[n]))]));
  const accepted=metrics.firstAcceptedSec.population;
  const reachedBy90=rows.filter(row=>row.firstAcceptedSec!==null&&row.firstAcceptedSec<=5400).length;
  const firstMedianPass=accepted.p50!==null&&accepted.p50>=2700&&accepted.p50<=3600;
  const deadlinePass=reachedBy90>=18;
  const lastMedian=metrics.h70EligibleSec.population.p50;
  const finalMedianPass=!r.screening&&lastMedian!==null&&lastMedian>=28800&&lastMedian<=43200;
  const passed=firstMedianPass&&deadlinePass&&(r.screening||finalMedianPass);
  check(r.targets.passed===passed,label+' target verdict');
  const target=id=>r.targets.checks.find(c=>c.id===id);
  check(target('first-reincarnation-median').observedSec===accepted.p50,label+' reported population median');
  check(target('first-reincarnation-deadline').reached===reachedBy90&&target('first-reincarnation-deadline').samples===20,label+' reported deadline denominator');
  if(!r.screening)check(target('last-unlock-median').observedSec===lastMedian,label+' reported final median');
  for(const scenario of r.scenarios){
   const checkpointRows=r.runs.map(run=>run.checkpoints.find(c=>c.minutes===scenario.minutes));
   for(const name of [...firstNames,'lastUnlockSec',...numberFields]){
    const s=stats(checkpointRows.map(c=>c[name])),reported=scenario.metrics[name];
    for(const key of ['samples','reached','unreached'])check(reported[key]===s[key],label+' conditional summary '+name+'/'+key);
    for(const key of ['p10','p50','p90'])check(reported[key]===s.conditional[key],label+' conditional summary '+name+'/'+key);
   }
  }
  const milestoneMetrics=protocol.milestones.map(m=>({id:m.id,kind:m.kind,final:m.final,requirements:m.requirements,
   eligible:stats(r.runs.map(run=>event(run,m.kind==='hero'?'eligibleHero':'eligibleMonster',m.id))),
   seen:stats(r.runs.map(run=>event(run,m.kind==='hero'?'seenHero':'seenMonster',m.id))),
   acquired:stats(r.runs.map(run=>event(run,m.kind==='hero'?'chosenHero':'killedMonster',m.id))),
   ...(m.kind==='monster'?{captured:stats(r.runs.map(run=>event(run,'capturedMonster',m.id)))}:{})}));
  let prefixComparison=null;
  if(exp.kind==='candidate'){
   const prefixes=r.runs.map(prefixFor),comparisons=prefixes.map(p=>{
    const reference=prefixReference.prefixes.find(x=>x.seed===p.seed);
    return {seed:p.seed,firstEventsMatch:equal(p.firstEvents,reference.firstEvents),
     recordsMatch:equal(p.recordsThroughFirstChoice,reference.recordsThroughFirstChoice),
     actionsMatch:equal(p.actionsThroughFirstChoice,reference.actionsThroughFirstChoice),
     actualSha256:objectHash(p),referenceSha256:objectHash(reference)};
   });
   const matched=comparisons.filter(p=>p.firstEventsMatch&&p.recordsMatch&&p.actionsMatch).length;
   prefixComparison={referencePath:prefixPath,referenceFileSha256:prefixHash,
    scope:prefixReference.scope,samples:20,matched,passed:matched===20,perSeed:comparisons};
   check(prefixComparison.passed,label+' recorded first journey prefix pairing');
   if(r.screening){
    const capture=execution.prefixComparison;
    check(capture&&hash(readFileSync(capture.path))===capture.sha256,label+' Host prefix file hash');
    const captured=read(capture.path);
    check(equal(captured.actualPrefixes,prefixes)&&captured.samples===20&&equal(captured.differentSeeds,comparisons.filter(p=>!p.firstEventsMatch||!p.recordsMatch||!p.actionsMatch).map(p=>p.seed)),label+' Host prefix raw pairing');
    check(captured.reference.sha256===prefixHash&&captured.report.sha256===hash(reportBytes),label+' Host prefix report/reference binding');
    check(capture.passed===prefixComparison.passed&&captured.passed===prefixComparison.passed,label+' Host prefix verdict');
    prefixComparison.hostArtifact={path:capture.path,sha256:capture.sha256};
   }
  }
  const choices=run=>run.actions.filter(a=>a.type==='heroChoose');
  const checkpoint=(run,m)=>run.checkpoints.find(c=>c.minutes===m);
  const full12hDiagnostics=r.screening?null:{
   nthHeroChoice:[1,3,5,7,8,9,10,15,20].map(n=>({n,...stats(r.runs.map(run=>choices(run)[n-1]?.sec??null))})),
   lastHeroChoiceSec:stats(rows.map(row=>row.lastHeroChoiceSec)),
   noHeroChoiceAfter8h:rows.filter(row=>row.lastHeroChoiceSec!==null&&row.lastHeroChoiceSec<=28800).length,
   killsAdded8to12h:stats(r.runs.map(run=>checkpoint(run,720).kills-checkpoint(run,480).kills)),
   partyPowerUnchanged8to12h:r.runs.filter(run=>checkpoint(run,720).partyPower===checkpoint(run,480).partyPower).length,
   distinctActualChosen:stats(rows.map(row=>row.distinctChosenHeroIds.length)),
   reincarnationsAdded8to12h:stats(rows.map(row=>row.post8h.reincarnationsAdded)),
   distinctChosenAdded8to12h:stats(rows.map(row=>row.post8h.distinctChosenAdded)),
   seenGap2to12h:stats(rows.map(row=>row.seenGap2to12h.longestGapSec)),
   acquiredGap2to12h:stats(rows.map(row=>row.acquiredGap2to12h.longestGapSec)),
   h70Before8h:rows.filter(row=>row.h70EligibleSec!==null&&row.h70EligibleSec<28800).length,
   h70Within8to12h:rows.filter(row=>row.h70EligibleSec!==null&&row.h70EligibleSec>=28800&&row.h70EligibleSec<=43200).length,
   roster30Level1By8h:r.runs.filter(run=>checkpoint(run,480).companions===30&&checkpoint(run,480).maxCompanionLevel===1).length
  };
  const detail={id:exp.id,kind:exp.kind,stage,path,fileSha256:hash(reportBytes),sourceDigest:r.sourceDigest,evaluationDigest:r.evaluationDigest,
   protocolSha256:r.protocolSha256,buildSha256:r.build.sha256,rawSha256:r.rawSha256,experiment:r.experiment,
   manifestPath,manifestFileSha256:hash(readFileSync(manifestPath)),binding:manifest.binding,
   horizonMinutes:r.timing.modeledMinutes,seeds:r.seeds,policy:canonical,metrics,
   deadline:{reached:reachedBy90,samples:20,deadlineSec:5400,required:18,passed:deadlinePass},
   checks:{firstMedianPass,deadlinePass,finalMedianStatus:r.screening?'NOT_EVALUATED':finalMedianPass?'PASS':'FAIL',passed},
   milestoneMetrics,checkpoints:r.checkpointsMinutes.map(minutes=>({minutes,metrics:Object.fromEntries(numberFields.map(n=>[n,stats(r.runs.map(run=>run.checkpoints.find(c=>c.minutes===minutes)[n]))]))})),
   prefixComparison,full12hDiagnostics,
   exactCheckpointMetrics:r.checkpointsMinutes.map(minutes=>({minutes,metrics:Object.fromEntries(['heroDamage','companionDamage','partyPower'].map(n=>[n,exactStats(r.runs.map(run=>checkpoint(run,minutes)[n]))]))})),
   perSeed:rows};
  reports.push(detail);
 }
}
const allExperimentsComplete=variants.length===expected.length&&variants.every(v=>v.status==='COMPLETED');
const screeningReports=reports.filter(r=>r.stage==='screening');
const requiredFull12hIds=screeningReports.filter(r=>r.checks.passed).map(r=>r.id);
const requiredReportCount=expected.length+requiredFull12hIds.length;
if(allExperimentsComplete){
 check(screeningReports.length===expected.length,'all eight completed experiments have screening reports');
 check(reports.length===requiredReportCount,'completed report count matches preregistered screening promotion');
 for(const id of requiredFull12hIds)check(reports.some(r=>r.id===id&&r.stage==='full12h'),id+' passing screening has full12h report');
 for(const r of reports.filter(r=>r.stage==='full12h'))check(requiredFull12hIds.includes(r.id),r.id+' full12h promotion requires passing screening');
}
const passing=reports.filter(r=>r.stage==='full12h'&&r.checks.passed&&reports.some(s=>s.id===r.id&&s.stage==='screening'&&s.checks.passed))
 .map(r=>({id:r.id,kind:r.kind,tuple:[Math.abs(r.metrics.firstAcceptedSec.population.p50-3150),Math.abs(r.metrics.h70EligibleSec.population.p50-36000),r.metrics.firstAcceptedSec.population.p90,r.id]}))
 .sort((a,b)=>a.tuple[0]-b.tuple[0]||a.tuple[1]-b.tuple[1]||(a.tuple[2]??Infinity)-(b.tuple[2]??Infinity)||(a.id<b.id?-1:a.id>b.id?1:0));
const repeatedControls = reports.filter(r=>r.kind==='control'&&r.stage==='screening').map(r=>{
